#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_set<long long> seen;
    bool found = false;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        if (seen.count(a[i])) {
            found = true;
            answer = a[i];
            break;
        }
        seen.insert(a[i]);
    }
    if (found) cout << answer << "\n";
    else cout << "none\n";

    return 0;
}

